#include <bits/stdc++.h>
using namespace std;

long long a, b, c, d, e, f, g, h, i, j, k;

int main() {
    cin >> a >> b >> c;
    cin >> d >> e;

    h = (d - 1) / (b * c) + 1;
    i = (e - 1) / (b * c) + 1;
    d -= (h - 1) * (b * c);
    e -= (i - 1) * (b * c);
    j = (d - 1) / c + 1;
    k = (e - 1) / c + 1;
    f = min((j - 1) * 5, 10 + j - 1);
    g = min((k - 1) * 5, 10 + k - 1);

    if (h > i) {
        swap(h, i);
    }

    if (h == i) {
        d = abs(j - k);
        cout << min(d * 5, 10 + d) << endl;
    } else {
        cout << k + g + min(i - h, h + a - i) * 15 << endl;
    }

    return 0;
}

